  for (int i = 1; i <= n; i++) {
    cin >> a[i];
  }
  for (int i = 1; i <= n; i++) {
    cin >> b[i];
  }
  for (int i = 1; i <= n; i++) {
    pq.push({a[i] + b[1], i, 1});
  }
  for (int i = 1; i <= n; i++) {
    cout << pq.top().sum << ' ';
    node now = pq.top();
    pq.pop();
    pq.push({a[now.i] + b[now.j + 1], now.i, now.j + 1});
  }
  return 0;
